const input = $json.body ?? $json;
if (!input.leadId || !input.tenantId || !Array.isArray(input.conversation)) throw new Error('Conversation summary input is invalid');
const userTurns = input.conversation.filter((message) => message.role === 'user').map((message) => String(message.content ?? '').trim()).filter(Boolean);
const assistantTurns = input.conversation.filter((message) => message.role === 'assistant').map((message) => String(message.content ?? '').trim()).filter(Boolean);
const contactValues = Object.values(input.leadData ?? {}).filter((value) => typeof value === 'string');
const contactTurns = /^(?:\[NAME_\d+\]|\[EMAIL_\d+\]|\[PHONE_\d+\])$/u;
const contextTurns = userTurns.filter((turn) => {
  const normalized = turn.replace(/[\s.!?,;:]+$/gu, '');
  return !contactValues.includes(normalized) && !contactTurns.test(normalized);
});
const customerRequest = contextTurns.at(-1) ?? 'follow-up requested';
const projectContext = contextTurns.find((turn) => turn !== customerRequest);
const humanIntent = String(input.intent ?? 'lead.capture').replaceAll('.', ' ');
const humanQuality = String(input.quality ?? 'unknown').replace(/^\w/u, (letter) => letter.toUpperCase());
const contact = input.leadData?.email ?? input.leadData?.phone ?? 'Not provided';
const summary = [
  `Customer request: ${customerRequest}`,
  ...(projectContext ? [`Project context: ${projectContext}`] : []),
  `Contact: ${input.leadData?.name ?? 'Not provided'} · ${contact}`,
  `Intent: ${humanIntent}.`,
  `Lead quality: ${humanQuality} (${input.score ?? 'unknown'}/100).`,
  `Validation: ${input.validationPass === true ? 'Passed' : 'Not passed'}.`,
  `Conversation: ${userTurns.length} visitor message(s), ${assistantTurns.length} assistant response(s).`,
].join('\n').slice(0, 20000);
return [{ json: { leadId: input.leadId, tenantId: input.tenantId, summary } }];
